/*
 * prog56_kruskal_mst – reconstructed source
 *
 * Behaviour (as observed from the original binary):
 *   * Exactly one command‑line argument is required: the number of vertices.
 *     It must be a non‑negative decimal integer with no extra characters.
 *     If the argument is missing or malformed the program prints
 *
 *         INVALID_ARGS
 *
 *     and exits.
 *   * The program then reads from stdin a list of edges, one per line,
 *     each line containing three decimal integers: u v w (end‑points and weight).
 *     The original binary limited the number of edges to 9, so we do the same.
 *   * It runs Kruskal's algorithm using a union‑find structure.
 *   * If the resulting set of edges does not connect all vertices the program
 *     prints
 *
 *         DISCONNECTED
 *
 *   * Otherwise it prints the total weight of the MST followed by the list of
 *     edges that belong to the MST, in the order they were selected.  The exact
 *     format (matching the strings found in the binary) is:
 *
 *         weight=%d edges=%d-%d,%d-%d,...\n
 *     i.e. after the word "edges=" each edge is printed as "u‑v".  A comma
 *     separates successive edges, and a final newline terminates the line.
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_EDGES 9      /* original binary limit */
#define MAX_VERTICES 6   /* original binary limit (observed in code) */

typedef struct {
    int u, v;
    int w;
} Edge;

typedef struct {
    int parent;
    int rank;
} UFNode;

static int uf_find(UFNode *uf, int x)
{
    if (uf[x].parent != x)
        uf[x].parent = uf_find(uf, uf[x].parent);
    return uf[x].parent;
}

static void uf_union(UFNode *uf, int x, int y)
{
    int rx = uf_find(uf, x);
    int ry = uf_find(uf, y);
    if (rx == ry) return;
    if (uf[rx].rank < uf[ry].rank) {
        uf[rx].parent = ry;
    } else if (uf[rx].rank > uf[ry].rank) {
        uf[ry].parent = rx;
    } else {
        uf[ry].parent = rx;
        uf[rx].rank++;
    }
}

static int cmp_edge(const void *a, const void *b)
{
    const Edge *ea = (const Edge *)a;
    const Edge *eb = (const Edge *)b;
    if (ea->w != eb->w)
        return (ea->w < eb->w) ? -1 : 1;
    if (ea->u != eb->u)
        return (ea->u < eb->u) ? -1 : 1;
    return (ea->v < eb->v) ? -1 : 1;
}

int main(int argc, char **argv)
{
    /* ---------- argument handling ---------- */
    if (argc < 2) {
        puts("INVALID_ARGS");
        return 0;
    }
    char *endptr;
    long n_vertices = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n_vertices <= 0 || n_vertices > MAX_VERTICES) {
        puts("INVALID_ARGS");
        return 0;
    }

    /* ---------- read edges ---------- */
    Edge edges[MAX_EDGES];
    int edge_cnt = 0;
    while (edge_cnt < MAX_EDGES) {
        int u, v, w;
        int rc = scanf("%d %d %d", &u, &v, &w);
        if (rc == EOF || rc < 3) break;
        edges[edge_cnt].u = u;
        edges[edge_cnt].v = v;
        edges[edge_cnt].w = w;
        edge_cnt++;
    }

    /* ---------- Kruskal ---------- */
    qsort(edges, edge_cnt, sizeof(Edge), cmp_edge);

    UFNode uf[MAX_VERTICES];
    for (int i = 0; i < n_vertices; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }

    Edge mst[MAX_EDGES];
    int mst_cnt = 0;
    int total_weight = 0;

    for (int i = 0; i < edge_cnt && mst_cnt < n_vertices - 1; ++i) {
        int ru = uf_find(uf, edges[i].u);
        int rv = uf_find(uf, edges[i].v);
        if (ru != rv) {
            uf_union(uf, ru, rv);
            mst[mst_cnt] = edges[i];
            total_weight += edges[i].w;
            mst_cnt++;
        }
    }

    /* ---------- output ---------- */
    if (mst_cnt != n_vertices - 1) {
        puts("DISCONNECTED");
        return 0;
    }
    printf("weight=%d edges=", total_weight);
    for (int i = 0; i < mst_cnt; ++i) {
        if (i > 0) putchar(',');
        printf("%d-%d", mst[i].u, mst[i].v);
    }
    putchar('\n');
    return 0;
}
